CREATE DATABASE IF NOT EXISTS tmtmine CHARACTER SET utf8mb4; USE tmtmine;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,telegram_id BIGINT NOT NULL UNIQUE,username VARCHAR(100),first_name VARCHAR(100),balance_usdt DECIMAL(18,8) DEFAULT 0,tmt_balance DECIMAL(18,8) DEFAULT 0,spins INT DEFAULT 0,referred_by BIGINT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE transactions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,type ENUM('deposit','withdraw','claim','spin_reward','referral') NOT NULL,amount DECIMAL(18,8) DEFAULT 0,status ENUM('pending','approved','rejected') DEFAULT 'pending',note VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE tasks(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,reward DECIMAL(18,8) DEFAULT 0,active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE settings(setting_key VARCHAR(100) PRIMARY KEY,setting_value TEXT);